const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

const BASE_URL = 'https://staging.247software.com';
const USERNAME  = 'Pranay';
const PASSWORD  = 'Pranay@1234';
const SCREENSHOTS_DIR = path.resolve(__dirname, '../screenshots');
const LOGS_DIR        = path.resolve(__dirname, '../logs');

[SCREENSHOTS_DIR, LOGS_DIR].forEach(d => { if (!fs.existsSync(d)) fs.mkdirSync(d, { recursive: true }); });

const results = [];

// ─── helpers ────────────────────────────────────────────────────────────────

function record(id, title, status, error, screenshot) {
  const entry = {
    id, title, status,
    error:      error      ? String(error).slice(0, 600) : null,
    screenshot: screenshot || null,
    timestamp:  new Date().toISOString()
  };
  results.push(entry);
  const icon = status === 'PASS' ? 'PASS' : status === 'SKIP' ? 'SKIP' : 'FAIL';
  console.log(`[${icon}] ${id} — ${title}${error ? ' | ' + String(error).slice(0, 120) : ''}`);
}

async function launch() {
  return chromium.launch({ headless: true, args: ['--no-sandbox', '--disable-setuid-sandbox'] });
}

async function loginAndGetPage(browser) {
  const ctx  = await browser.newContext({ ignoreHTTPSErrors: true });
  const page = await ctx.newPage();
  page.setDefaultTimeout(20000);

  await page.goto(BASE_URL, { waitUntil: 'domcontentloaded', timeout: 30000 });

  // Fill login form
  await page.fill('input[name="username"]', USERNAME);
  await page.fill('input[name="password"], input[type="password"]', PASSWORD);

  // Submit — the login uses AJAX; wait for network response
  await Promise.all([
    page.waitForResponse(r => r.url().includes('/authenticate') && r.status() === 200, { timeout: 20000 }),
    page.click('#login_btn, button[type="submit"], input[type="submit"], button:has-text("Login"), button:has-text("Sign In")')
  ]);

  await page.waitForTimeout(3000);
  return { ctx, page };
}

async function screenshot(page, id) {
  const p = path.join(SCREENSHOTS_DIR, `${id}.png`);
  try { await page.screenshot({ path: p, fullPage: true }); } catch (_) {}
  return p;
}

async function navigateToEventTypes(page) {
  // The app may use hash-routing or direct routes — try multiple strategies
  try {
    // Strategy 1: direct URL navigation
    await page.goto(`${BASE_URL}/#/eventType`, { waitUntil: 'domcontentloaded', timeout: 15000 });
    await page.waitForTimeout(2000);
    const h = await page.content();
    if (h.includes('Event Type') || h.includes('event_type') || h.includes('eventType')) return true;
  } catch (_) {}

  try {
    // Strategy 2: look for nav link text
    const navLink = page.locator('a:has-text("Event Type"), a[href*="eventType"], a[href*="event-type"]').first();
    if (await navLink.isVisible({ timeout: 5000 }).catch(() => false)) {
      await navLink.click();
      await page.waitForTimeout(2000);
      return true;
    }
  } catch (_) {}

  try {
    // Strategy 3: Setup menu
    const setupMenu = page.locator('a:has-text("Setup"), span:has-text("Setup"), li:has-text("Setup")').first();
    if (await setupMenu.isVisible({ timeout: 5000 }).catch(() => false)) {
      await setupMenu.click();
      await page.waitForTimeout(1000);
      const etLink = page.locator('a:has-text("Event Type"), a[href*="eventType"]').first();
      if (await etLink.isVisible({ timeout: 5000 }).catch(() => false)) {
        await etLink.click();
        await page.waitForTimeout(2000);
        return true;
      }
    }
  } catch (_) {}

  return false;
}

