async function TC003_createEventTypeValid() {
  const id = 'TC-003'; const title = 'Create a new Event Type with valid data';
  const browser = await launch();
  try {
    const { page } = await loginAndGetPage(browser);
    await navigateToEventTypes(page);

    // Look for Add/New/Create button
    const addBtn = page.locator(
      'button:has-text("Add"), button:has-text("New"), button:has-text("Create"), ' +
      'a:has-text("Add"), a:has-text("New Event Type"), [class*="add"], [class*="create"], ' +
      'button[class*="btn-primary"]:visible, .fa-plus'
    ).first();

    let created = false;
    if (await addBtn.isVisible({ timeout: 8000 }).catch(() => false)) {
      await addBtn.click();
      await page.waitForTimeout(2000);

      // Fill name field
      const nameField = page.locator(
        'input[name="event_type"], input[placeholder*="ame"], input[name*="name"], ' +
        'input[id*="event"], input[type="text"]:visible'
      ).first();
      if (await nameField.isVisible({ timeout: 5000 }).catch(() => false)) {
        await nameField.fill('TestEventType_Auto');

        // Click Save
        const saveBtn = page.locator(
          'button:has-text("Save"), button:has-text("Submit"), button:has-text("Add"), ' +
          'input[type="submit"], button[type="submit"]'
        ).first();
        if (await saveBtn.isVisible({ timeout: 3000 }).catch(() => false)) {
          await saveBtn.click();
          await page.waitForTimeout(3000);
          const content = await page.content();
          created = content.includes('TestEventType_Auto') ||
                    content.toLowerCase().includes('success') ||
                    content.toLowerCase().includes('saved') ||
                    content.toLowerCase().includes('created');
        }
      }
    } else {
      // Button not found — possibly behind a different UI pattern
      created = null; // SKIP
    }

    const ss = await screenshot(page, id);
    if (created === null) {
      record(id, title, 'SKIP', 'Add button not found — UI pattern may differ from expected', ss);
    } else if (created) {
      record(id, title, 'PASS', null, ss);
    } else {
      record(id, title, 'FAIL', 'Event Type creation not confirmed in response', ss);
    }
  } catch (e) {
    record(id, title, 'FAIL', e, path.join(SCREENSHOTS_DIR, `${id}.png`));
  } finally { await browser.close(); }
}

